/* Buyers' pictures on cart lines (round AG3, run after `164`): a product form's photo upload (an imported theme's `properties[Photo]` file, the Storelib theme's Personalization block, POST /cart/upload) is kept in the new PRIVATE `cart-uploads` bucket (10 MB, JPEG, PNG and WebP only, no storage policy at all, so only the server reads or writes it) under the store and a random id, with its row in the new `cart_uploads` table (the store, the SHA-256 of the browser's own cart id, the file's name, type, size and pixels, its path while in a cart and its path once a paid order took it). No anon or authenticated access: row level security on, nothing granted but to the service role. New table and bucket only; no existing row changes. Until it runs, a product form with a picture is told uploads are not available yet and everything else works as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.cart_uploads (id uuid PRIMARY KEY, creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, visitor_hash text NOT NULL CHECK (visitor_hash ~ '^[0-9a-f]{64}$'), file_name text NOT NULL CHECK (length(file_name) BETWEEN 1 AND 90), content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')), bytes integer NOT NULL CHECK (bytes > 0 AND bytes <= 10485760), width integer CHECK (width IS NULL OR width > 0), height integer CHECK (height IS NULL OR height > 0), cart_path text CHECK (cart_path IS NULL OR (cart_path LIKE 'cart/%' AND position('..' in cart_path) = 0)), order_path text CHECK (order_path IS NULL OR (order_path LIKE 'orders/%' AND position('..' in order_path) = 0)), checkout_id uuid REFERENCES public.commerce_checkouts(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), claimed_at timestamptz, attached_at timestamptz);
CREATE INDEX IF NOT EXISTS cart_uploads_creator_idx ON public.cart_uploads (creator_id, created_at DESC);
CREATE INDEX IF NOT EXISTS cart_uploads_unattached_idx ON public.cart_uploads (created_at) WHERE attached_at IS NULL;
CREATE INDEX IF NOT EXISTS cart_uploads_checkout_idx ON public.cart_uploads (checkout_id) WHERE checkout_id IS NOT NULL;
ALTER TABLE public.cart_uploads ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.cart_uploads FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cart_uploads TO service_role;
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('cart-uploads', 'cart-uploads', false, 10485760, ARRAY['image/jpeg', 'image/png', 'image/webp']) ON CONFLICT (id) DO UPDATE SET public = false, file_size_limit = 10485760, allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp'];
notify pgrst, 'reload schema';
